因:叮人=只有母蚊要吸血，血裡的蛋白質是牠產卵需要的；牠是靠人呼出的二氧化碳、體溫和汗味找到人的
因:叮了會癢/會癢/癢/叮會癢=蚊子叮人時會注入唾液防止血液凝固，身體對唾液起過敏反應、釋放組織胺，所以會腫、會癢
因:喜歡咬/咬我/叮我/愛咬/特別喜歡/被咬=蚊子靠二氧化碳、體溫、汗味和皮膚的氣味找人：呼出比較多二氧化碳（體型大、剛運動完、孕婦）、體溫比較高、流汗、喝了酒的人比較容易被叮；穿深色衣服也比較顯眼；每個人皮膚上的細菌產生的氣味不同，所以有人特別招蚊子。血型的影響，研究結果還不一致
@蟑螂|小強|動物
簡介=生命力很強的昆蟲，已經在地球上存在了 3 億年
是=昆蟲、動物
吃=幾乎什麼都吃
會=飛（有些種類）、跑得很快
腳=6 隻
@鴿子|鴿|動物
簡介=很會認路的鳥，古代被用來送信
是=鳥類、動物
吃=種子、穀物
會=飛、從很遠的地方飛回家
腳=2 隻
@天鵝|鵝|動物
簡介=優雅的大型水鳥，大多是白色的
是=鳥類、動物
吃=水草、小動物
會=飛、游泳
腳=2 隻
說明=澳洲有黑天鵝
@孔雀|雀|動物
簡介=開屏很漂亮的大型鳥
是=鳥類、動物
吃=種子、昆蟲、小動物
會=飛（短距離）、開屏
說明=只有公孔雀有漂亮的長尾巴，開屏是為了吸引母孔雀
@蝸牛|蝸|動物
簡介=背著殼慢慢爬的軟體動物
是=軟體動物、動物
吃=植物的葉子
說明=蝸牛有好幾千顆非常小的牙齒（齒舌）
@海星|星魚|動物
簡介=星星形狀的海洋動物，手斷了可以再長回來
是=棘皮動物、動物
吃=貝類
住=海洋
說明=海星不是魚，沒有大腦和血液
@蚯蚓|地龍|動物
簡介=住在土裡、幫助土壤變肥沃的動物
是=環節動物、動物
吃=土裡的腐爛植物
會=鬆土
說明=蚯蚓沒有眼睛，用皮膚感光和呼吸
因:下雨爬出來=下大雨時土裡積水，蚯蚓用皮膚呼吸，太濕了不好呼吸，所以爬到地面上
@倉鼠|黃金鼠,三線鼠,楓葉鼠,寵物鼠|動物
簡介=體型小、常被當寵物養的囓齒動物，臉頰有可以塞食物的頰囊
是=哺乳類、囓齒類、動物
吃=倉鼠專用飼料、穀物、種子，可以少量給一點蔬菜和水果，不能吃巧克力、洋蔥、柑橘
會=把食物塞在頰囊裡帶回窩藏起來、在滾輪上跑很久
壽命=大約 2 到 3 年
說明=倉鼠是夜行性動物，晚上比較活躍；大多喜歡獨居，兩隻養在一起容易打架
@太陽|日頭,太陽公公|天體
簡介=太陽系中心的恆星，是一顆由氫和氦組成的熾熱氣體球，地球上的光和熱幾乎都來自它
是=恆星、天體
距離=離地球大約 1.5 億公里，太陽光要大約 8 分 20 秒才到地球
溫度=表面大約 5,500°C，核心大約 1,500 萬°C
年齡=大約 46 億年
大小=直徑大約是地球的 109 倍，可以裝下 130 萬個地球
說明=太陽是恆星，自己會發光；地球和月亮都不會自己發光
因:從東邊升起/東邊/升起=地球由西向東自轉，所以我們看到太陽從東邊升起、往西邊落下
因:發光/發熱/熱=太陽核心的溫度和壓力極高，氫原子核融合成氦，釋放出巨大的能量，變成光和熱
顏色=其實是白色的（各種顏色的光混在一起）；我們看起來偏黃，是因為大氣把藍光散射掉了，日出日落時看起來更紅更橘
@月亮|月球,月|天體
簡介=地球唯一的天然衛星，繞著地球轉
是=衛星、天體
距離=離地球平均大約 38.4 萬公里
大小=直徑大約 3,474 公里，大約是地球的四分之一
繞一圈=繞地球一圈大約 27.3 天；從滿月到下一次滿月大約 29.5 天
說明=月亮自己不會發光，我們看到的月光是反射的太陽光
因:發光/亮/會亮=月亮自己不會發光，月光是它反射的太陽光
因:圓缺/形狀/變/陰晴圓缺/月相=月亮繞著地球轉，太陽照亮的那一半，被我們看到的部分每天不同，所以看起來有新月、上弦月、滿月、下弦月的變化
因:跟著我走/跟著走=月亮離我們非常遠，走路時旁邊的房子、樹位置變化很大，月亮的方向幾乎不變，看起來就像在跟著你走
因:只看到同一面/同一面=月亮自轉一圈和繞地球一圈的時間一樣長（潮汐鎖定），所以總是同一面對著地球
因:跟著/跟著人走/跟著我走/跟著我們走=月亮離我們大約 38 萬公里，非常遠；你走路時，路邊的樹和房子很近，看起來一下子就往後跑，但月亮太遠了，角度幾乎不變，看起來就像一直跟著你走
重量=大約 7.35 × 10²² 公斤，是地球的 1/81 左右
@地球|地表|天體
簡介=太陽系的第三顆行星，是目前唯一知道有生命的星球
是=行星、天體
形狀=接近球形，赤道稍微鼓起、兩極稍扁
年齡=大約 45.4 億年
大小=赤道周長大約 40,075 公里，直徑大約 12,742 公里
自轉=自轉一圈大約 24 小時（嚴格說是 23 小時 56 分）
公轉=繞太陽一圈大約 365.25 天，就是一年
衛星=1 顆（月亮）
海洋=表面大約 71% 是海洋
說明=地球是圓的：從太空拍的照片、船從遠方先露出桅杆、月食時地球在月亮上的影子是圓的，都能證明
因:四季/季節=地球的自轉軸傾斜大約 23.5 度，繞太陽時，一年中太陽直射的位置在南北回歸線之間移動，陽光照射的角度和白天長短跟著變，才有四季
因:白天黑夜/白天/黑夜/晝夜=地球自轉，面向太陽的一面是白天，背向太陽的一面是黑夜
因:轉/自轉=地球是由旋轉的氣體和塵埃雲聚成的，形成時就帶著旋轉，太空中幾乎沒有阻力，所以一直轉下去
大洲=7 個（亞洲、非洲、北美洲、南美洲、南極洲、歐洲、大洋洲）
大洋=5 個（太平洋、大西洋、印度洋、南冰洋、北冰洋）
因:圓/是圓的/為什麼是圓的=地球的質量很大，引力會從四面八方把物質往中心拉，最後拉成最穩定的球形；因為會自轉，赤道比兩極稍微鼓一點，其實是有點扁的球
重量=大約 5.97 × 10²⁴ 公斤（59.7 萬億億噸）
@太陽系|太陽系行星|天體
簡介=以太陽為中心，加上繞著它轉的八大行星、矮行星、小行星和彗星
行星=8 顆：水星、金星、地球、火星、木星、土星、天王星、海王星
說明=冥王星在 2006 年被重新分類為矮行星，所以現在是八大行星
@水星|水星|天體
簡介=離太陽最近、也是最小的行星
是=行星、天體
說明=水星上沒有水，名字來自中國古代的五行
特點=水星繞太陽一圈只要 88 天
@金星|啟明星,長庚星|天體
簡介=太陽系最熱的行星，也是夜空中除了月亮之外最亮的星
是=行星、天體
溫度=表面大約 465°C，比水星還熱，因為濃厚的二氧化碳大氣有強烈的溫室效應
特點=金星自轉的方向和大多數行星相反，在金星上太陽從西邊升起
@火星|紅色星球|天體
簡介=表面是紅色的岩石行星，是人類最想去探索的星球
是=行星、天體
衛星=2 顆：火衛一、火衛二
因:紅色/紅=火星表面的土壤和岩石含有很多氧化鐵，也就是鐵鏽，所以看起來是紅色的
@木星|木星|天體
簡介=太陽系最大的行星，是一顆氣體巨行星
是=行星、天體
大小=可以裝下大約 1,300 個地球
特點=木星上的大紅斑是一個比地球還大的風暴，已經持續了幾百年
@土星|土星|天體
簡介=有美麗光環的氣體巨行星
是=行星、天體
說明=土星環是由大量的冰塊和岩石碎片組成的
特點=土星的密度比水還小
@天王星|天王星|天體
簡介=躺著轉的冰巨行星
是=行星、天體
特點=天王星的自轉軸傾斜大約 98 度，像是側躺著繞太陽轉
@海王星|海王星|天體
簡介=離太陽最遠的行星，是風最強的行星
是=行星、天體
特點=海王星是用數學計算預測出位置、才被找到的行星
@冥王星|冥王星|天體
簡介=位在海王星外面的矮行星，以前被當成第九大行星
是=矮行星、天體
不是=行星（2006 年起不算行星）
說明=冥王星在 2006 年被國際天文學聯合會改列為矮行星，因為它沒有清空自己軌道附近的其他天體
@星星|恆星,星|天體
簡介=像太陽一樣會自己發光的遙遠恆星
因:眨眼/閃/一閃一閃=星光穿過地球的大氣層時，冷熱不同的空氣一直在流動，把光線折射得忽左忽右、忽明忽暗，看起來就在眨眼
因:白天看不到/白天=星星白天也在天上，只是太陽光太亮，被散射的陽光把天空照亮，蓋過了星光
@光|光線,光速|科學
簡介=一種電磁波，在真空中跑得最快
速度=在真空中每秒大約 30 萬公里（精確是每秒 299,792,458 公尺）
特點=光一秒可以繞地球大約 7 圈半
@聲音|聲速,音速|科學
簡介=物體振動造成的波，需要空氣、水或固體才能傳播
速度=在 20°C 的空氣中每秒大約 343 公尺；在水裡大約快 4 倍
說明=太空是真空，聲音傳不過去
因:先看到閃電後聽到雷/先看到閃電=光每秒跑 30 萬公里，聲音每秒只跑大約 340 公尺，所以先看到閃電、後聽到雷聲
@天空|藍天|自然
簡介=我們從地面往上看到的大氣層
因:藍/藍色=陽光是由各種顏色的光混在一起，穿過大氣時，空氣分子對波長短的藍光散射得比紅光強很多（瑞利散射），藍光被散到整片天空，所以天空看起來是藍的
因:夕陽/紅/紅色/橘/黃昏=傍晚太陽斜射，陽光要穿過很厚的大氣，藍光在途中幾乎都被散射掉，剩下的紅光、橙光到達我們眼睛，所以夕陽和晚霞是紅的
因:黑/晚上=晚上我們背對太陽，沒有陽光被空氣散射，天空就是黑的
顏色=晴天的白天是藍色的（陽光被空氣散射，藍光散得最多）；日出、日落時偏紅、橘色，因為陽光要穿過更厚的大氣，藍光都被散掉了
@夕陽|晚霞,落日,夕照|自然
簡介=傍晚快要落下的太陽，和被它染紅的天空
因:紅/紅色/橘/橘色/黃色=傍晚太陽斜射，陽光要穿過很厚的大氣，藍光在途中幾乎都被散射掉，剩下的紅光、橙光到達我們眼睛，所以夕陽和晚霞是紅的
@彩虹|虹|自然
簡介=陽光照到空中的小水滴，被分成七種顏色的弧形光帶
顏色=7 種：紅、橙、黃、綠、藍、靛、紫（其實顏色是連續變化的）
因:出現/形成/會有=陽光射進空中的小水滴，在水滴裡折射、反射再折射出來，不同顏色的光偏折的角度不同，就分開成一條彩色的光帶；所以彩虹總是出現在背對太陽、前方有水氣的時候，常見在雨後
因:彎/弧形/彎的=每一種顏色的光都是在和太陽相反方向固定的角度（大約 42 度）上被我們看到，這些點連起來就是一個圓弧
@打雷|雷,雷聲,閃電,打雷閃電|自然
簡介=雷雨雲裡累積的電荷放電時的光和聲音
因:打雷/雷/會打雷/閃電/形成=雷雨雲裡的冰晶和水滴上下碰撞，把正負電荷分開，累積到很高的電壓時就放電，這就是閃電；閃電瞬間把空氣加熱到大約 3 萬度，空氣急速膨脹發出的巨響就是雷聲
說明=打雷時不要站在空曠處或大樹下，躲進建築物或汽車裡比較安全
@雨|下雨,雨水|自然
簡介=雲裡的水滴變大、變重後掉下來
因:下雨/雨=太陽把海洋和地面的水曬成水蒸氣，水蒸氣上升遇冷凝結成小水滴形成雲，小水滴互相碰撞合併變大，重到空氣托不住時就掉下來，這就是雨
@雲|雲朵,白雲|自然
簡介=空中的小水滴和小冰晶聚在一起
因:白色/白=雲裡的水滴比空氣分子大很多，各種顏色的光都同樣被散射，混在一起就是白色
因:烏雲/黑/灰=雲很厚的時候，陽光穿不透，從下面看就是灰黑色的，常常表示快下雨了
因:浮/飄=雲裡的水滴非常小，上升的氣流就能托住它們
@風|颳風|自然
簡介=空氣的流動
因:風/颳風/有風=太陽把地面曬得不均勻，熱的地方空氣上升、氣壓變低，冷的地方氣壓高，空氣就從氣壓高的地方流向氣壓低的地方，形成風
@颱風|颶風,熱帶氣旋|自然
簡介=在溫暖海洋上形成的強烈熱帶氣旋，在西北太平洋叫颱風，在大西洋叫颶風
因:形成/颱風=夏秋季溫暖的海水讓大量水氣蒸發上升，凝結時放出熱量，讓空氣更快上升，周圍的空氣補進來，受地球自轉影響開始旋轉，越轉越強就成了颱風
說明=颱風的中心叫颱風眼，那裡反而風平浪靜
@地震|地震|自然
簡介=地殼突然錯動造成的震動
因:地震/形成/會地震=地球表面是由很多塊板塊拼成的，板塊一直在慢慢移動、互相擠壓，累積的能量超過岩層能承受的程度時突然斷裂、錯動，就發生地震
說明=台灣、日本在板塊交界上，所以地震特別多；地震時記得「趴下、掩護、穩住」
@潮汐|漲潮,退潮,潮水|自然
簡介=海水每天規律地漲退
因:潮汐/漲潮/退潮/形成=主要是月亮的引力（加上太陽的引力）拉著地球上的海水，面向月亮和背對月亮的兩邊海水隆起，地球自轉，所以大部分地方一天大約有兩次漲潮、兩次退潮
@海水|海|自然
簡介=覆蓋地球大約七成表面的鹹水
因:鹹/鹹的=雨水沖刷岩石，把裡面的鹽分礦物帶進河流，最後流進海裡；海水蒸發時只有水跑掉、鹽留下來，幾億年累積下來，海水就變鹹了
因:藍/藍色=水本身會吸收一點紅光，很深很多的水就呈現藍色，再加上反射天空的顏色
@水|H2O|科學
簡介=氫和氧組成的化合物，化學式是 H2O，是生命不能沒有的東西
沸點=100°C（在一大氣壓下；高山上氣壓低，大約 70 到 90 幾度就會滾）
冰點=0°C
密度=4°C 時最大，大約每立方公分 1 公克
說明=人體大約 60% 是水
因:冰浮在水上/冰浮/浮=水結冰時分子排成有空隙的結構，冰的密度比水小，所以會浮在水上；所以湖面結冰時，下面的魚還能活
化學式=H₂O：兩個氫原子和一個氧原子
成分=兩個氫原子和一個氧原子組成一個水分子（H₂O）
@冰|冰塊|科學
簡介=水在 0°C 以下結成的固體
因:浮/浮在水上=水結冰時分子排成有空隙的六角形結構，冰的密度比水小大約 9%，所以冰會浮在水上
因:滑=冰的表面有一層非常薄的類似液體的水層，加上壓力和摩擦生熱，所以很滑
@空氣|大氣|科學
簡介=包圍地球的氣體
成分=大約 78% 是氮氣、21% 是氧氣，剩下的是氬、二氧化碳和水氣等
@葉子|樹葉,葉|自然
簡介=植物進行光合作用、製造養分的地方
因:綠/綠色=葉子裡有很多葉綠素，葉綠素吸收紅光和藍光來進行光合作用，綠光反射出來，所以葉子是綠的
因:變黃/變紅/秋天/落葉/掉=秋天日照變短、天氣變冷，樹不再製造葉綠素，綠色退掉後，原本就有的黃色胡蘿蔔素顯現出來，有些樹還會製造紅色的花青素；落葉是樹為了過冬省水省能量，主動讓葉子脫落
@草|小草,草地,青草|自然
簡介=長在地上、莖比較軟的植物，牛羊這些草食動物的主要食物
是=植物
因:綠/綠色=草和樹葉一樣含有很多葉綠素，葉綠素吸收紅光和藍光來進行光合作用，把綠光反射出來，所以草看起來是綠的
因:變黃/枯=天氣冷、太乾或缺水時，草不再製造葉綠素，綠色退掉就變黃了
@光合作用|光合|科學
簡介=植物用陽光、水和二氧化碳製造養分（葡萄糖），同時放出氧氣
@鐵|鐵器|科學
簡介=最常用的金屬之一，地球的核心主要也是鐵和鎳
因:生鏽/鏽=鐵和空氣中的氧氣、水分起化學反應，生成氧化鐵，就是紅褐色的鐵鏽；所以潮濕的地方鐵特別容易生鏽
@四季|季節|自然
簡介=春、夏、秋、冬
因:四季/季節=地球的自轉軸傾斜大約 23.5 度，繞太陽時，一年中太陽直射的位置在南北回歸線之間移動，陽光照射的角度和白天長短跟著變，才有四季
@春天|春季,春|季節
月份=北半球一般說 3、4、5 月；農曆是正月到三月；天文上從春分（3 月 20 日左右）到夏至；南半球剛好相反，是 9 到 11 月
特點=節氣有立春、雨水、驚蟄、春分、清明、穀雨
@夏天|夏季,夏|季節
月份=北半球一般說 6、7、8 月；天文上從夏至（6 月 21 日左右）到秋分；南半球是 12 到 2 月
特點=節氣有立夏、小滿、芒種、夏至、小暑、大暑
@秋天|秋季,秋|季節
月份=北半球一般說 9、10、11 月；天文上從秋分（9 月 23 日左右）到冬至；南半球是 3 到 5 月
特點=節氣有立秋、處暑、白露、秋分、寒露、霜降
@冬天|冬季,冬|季節
月份=北半球一般說 12、1、2 月；天文上從冬至（12 月 21 日左右）到春分；南半球是 6 到 8 月
特點=節氣有立冬、小雪、大雪、冬至、小寒、大寒
@人|人體,人類,成年人,大人|人體
簡介=學名是智人，靠語言、合作和使用工具成為地球上最有影響力的物種
是=哺乳類、靈長類、動物
骨頭=成人有 206 塊骨頭；剛出生的嬰兒大約有 270 到 300 塊，長大時有些會癒合在一起
牙齒=成人有 32 顆恆牙（包含 4 顆智齒，有些人沒長齊）；小孩的乳牙有 20 顆
肌肉=600 多塊
心臟=1 顆，大約拳頭大小
心跳=成人安靜時每分鐘大約 60 到 100 下
體溫=正常大約 36.5 到 37.5°C
血液=成人大約有 4.5 到 5.5 公升，大約是體重的 7% 到 8%
大腦=大約 1.3 到 1.4 公斤
染色體=23 對，共 46 條
肺=2 個（左肺比右肺小一點，留空間給心臟）
腎臟=2 顆
最大的器官=皮膚
最長的骨頭=大腿骨（股骨）
最小的骨頭=耳朵裡的鐙骨，大約 3 公釐
水=身體大約 60% 是水
壽命=全世界平均大約 73 歲，台灣大約 80 歲，日本、義大利都超過 83 歲
因:睡覺/要睡覺/睡=睡覺時大腦會整理白天的記憶、清除代謝廢物，身體修復組織、分泌生長激素、調節免疫力；長期睡不夠，注意力、情緒、免疫力都會變差
因:做夢/夢=做夢大多發生在快速動眼期，科學家認為和大腦整理記憶、處理情緒有關，但確切原因還沒有定論
因:打哈欠/哈欠=打哈欠可能是在幫大腦降溫、讓自己清醒一點；看到別人打哈欠也會跟著打，和人的同理心、模仿有關
因:打噴嚏/噴嚏=鼻子裡有灰塵、花粉或病毒刺激時，身體用噴嚏把它們強力噴出去，是一種保護反射
因:打嗝/嗝=橫膈膜突然不自主地收縮，聲門同時關上，就發出「嗝」的聲音；吃太快、太飽、喝汽水都容易引起
因:雞皮疙瘩=冷或害怕時，皮膚上讓毛豎起來的小肌肉收縮，就起雞皮疙瘩；這是祖先毛多時用來保暖、讓自己看起來比較大的反應
因:肚子叫/肚子餓會叫/咕嚕=胃和腸子一直在蠕動推送食物和氣體，肚子空的時候沒有食物緩衝，聲音就特別明顯
因:流汗/出汗/汗=流汗是在散熱：汗水蒸發時會帶走皮膚的熱，讓體溫不要太高
因:發燒=發燒是身體在對抗病菌：大腦把體溫的設定點調高，較高的體溫讓病菌比較難繁殖、讓免疫系統更活躍
因:頭髮變白/白頭髮=頭髮的顏色來自黑色素細胞，年紀大了、壓力或遺傳的關係，黑色素細胞越來越少，頭髮就變白了
因:老/會老/變老=細胞每次分裂，染色體末端的端粒會變短，DNA 的損傷也會累積，細胞修復的能力慢慢變差，身體就漸漸老化
因:怕冷/會冷/覺得冷=人是恆溫動物，要把體溫維持在 37°C 左右；天冷時皮膚的血管收縮、身體開始發抖產熱，大腦就讓你「覺得冷」，提醒你加衣服。每個人怕冷的程度不同，跟肌肉量、體脂、血液循環、甲狀腺都有關
因:頭髮變白/白頭髮/頭髮會變白/變白/頭髮白=頭髮的顏色來自毛囊裡的黑色素細胞；隨著年紀增加（也和遺傳、壓力、營養有關），黑色素細胞慢慢變少、不再製造色素，長出來的頭髮就變白了
@洋蔥|洋葱|食物
簡介=常見的蔬菜，切開有辣味和香氣
是=蔬菜、植物
因:流淚/流眼淚/哭/辣眼睛=切洋蔥時細胞被切破，裡面的物質起反應，產生一種會揮發的含硫氣體，飄到眼睛裡刺激神經，眼睛就分泌眼淚把它沖掉；冰過再切、用很利的刀可以減少流淚
說明=貓狗不能吃洋蔥
@辣椒|辣|食物
簡介=有辣味的蔬菜，可以當調味料
是=蔬菜、植物
因:辣/會辣=辣椒裡的辣椒素會刺激舌頭上感覺「熱」的神經，大腦以為被燙到了，所以辣其實是一種痛覺，不是味覺
因:流汗/出汗/冒汗/臉紅=辣椒素刺激感覺「熱」的神經，大腦以為身體真的變熱了，就啟動散熱：流汗、臉紅、流鼻水，其實體溫並沒有真的升高
說明=吃太辣時喝牛奶比喝水更能解辣
@番茄|西紅柿,蕃茄,小番茄|食物
簡介=紅色多汁的果實，可以生吃也可以煮
是=水果、蔬菜、植物
說明=植物學上番茄是果實（漿果），所以算水果；但做菜、營養分類上常把它當蔬菜，兩種說法都對
@香蕉|蕉|食物
簡介=熱帶水果，軟、甜，方便攜帶
是=水果、植物
顏色=熟了是黃色，還沒熟是綠色，熟過頭會出現褐色斑點
說明=植物學上香蕉是漿果；香蕉樹其實是一種很大的草本植物
好處=含有鉀和容易吸收的醣類，運動前後吃可以補充能量
因:變黑/會變黑/黑掉=香蕉熟了以後，果皮裡的葉綠素分解，再加上酵素讓多酚氧化，就會出現黑色斑點；放冰箱時低溫會傷害果皮細胞，皮也會很快變黑，但裡面的果肉通常還好好的
@蘋果|蘋果|食物
簡介=最常見的水果之一，脆、酸甜
是=水果、植物
顏色=紅色最常見，也有綠色（青蘋果）和黃色的
因:變黃/變褐色/變色/氧化=蘋果切開後，細胞裡的酵素碰到空氣中的氧氣，把裡面的酚類物質氧化成褐色；泡一下鹽水或檸檬水可以減慢
@草莓|士多啤梨|食物
簡介=紅色的甜水果，表面有很多小顆粒
是=水果、植物
顏色=紅色
說明=草莓表面的小顆粒才是真正的果實（瘦果），紅色多汁的部分是膨大的花托
@西瓜|瓜|食物
簡介=夏天的消暑水果，大約九成以上是水
是=水果、植物
顏色=外皮綠色，果肉大多是紅色，也有黃色的
@花生|土豆,落花生|食物
簡介=長在土裡的豆子，可以炒、煮、做花生醬
是=豆類、植物
說明=花生名字裡常被當堅果，但植物學上是豆科植物的種子
@香菇|蘑菇,菇,菇類|食物
簡介=可以吃的菇類
是=真菌
說明=菇類不是植物，是真菌，不會進行光合作用
特點=香菇曬過太陽，維生素 D 會增加
@咖啡|咖啡豆|飲料
簡介=用咖啡豆烘焙研磨後沖泡的飲料，原產於非洲衣索比亞
好處=咖啡因可以提神、提升專注力；適量喝（一天大約 3 到 4 杯以內）的研究顯示和較低的第二型糖尿病、某些肝病風險有關
壞處=喝太多會心悸、焦慮、失眠；下午以後喝容易影響睡眠；孕婦一天的咖啡因建議不超過 200 毫克
因:提神=咖啡因會擋住大腦裡讓人想睡的「腺苷」受體，所以喝了比較清醒
營養=咖啡因（一杯美式大約 100 到 150 毫克）、抗氧化的多酚；黑咖啡幾乎沒有熱量，加糖和奶精才有
@茶|茶葉,綠茶,紅茶,烏龍茶|飲料
簡介=用茶樹的葉子做成的飲料，起源於中國
好處=含有茶多酚（抗氧化）和咖啡因，可以提神；綠茶、烏龍茶、紅茶都來自同一種茶樹，差別在發酵程度
壞處=空腹喝太濃容易傷胃，晚上喝可能睡不著
@牛奶|鮮奶|飲料
簡介=牛分泌的乳汁，含豐富的鈣和蛋白質
好處=是補充鈣質和蛋白質的好來源
說明=有些人乳糖不耐，喝了會脹氣或拉肚子，可以改喝無乳糖牛奶或優格
營養=蛋白質、鈣、維生素 B2 和 B12、維生素 D（有添加的）、鉀；一杯 240 毫升大約有 8 公克蛋白質、300 毫克鈣
@巧克力|朱古力|食物
簡介=用可可豆做成的甜食
說明=狗和貓不能吃巧克力，裡面的可可鹼對牠們有毒
好處=黑巧克力含有抗氧化的多酚，適量吃可以讓人心情好
壞處=牛奶巧克力糖分和熱量很高
@運動|健身|活動
簡介=讓身體動起來的活動
好處=強化心肺和肌肉、控制體重、改善睡眠、減輕壓力和焦慮、降低心臟病和糖尿病的風險
說明=世界衛生組織建議成人每週至少 150 分鐘中等強度的運動，例如快走
@喝水|多喝水,水分|活動
簡介=補充身體需要的水分
好處=幫助調節體溫、運送養分、排出廢物，喝夠水也比較不容易頭痛、便秘
說明=一般成人一天大約需要 1.5 到 2 公升，天熱或運動時要更多
@睡覺|睡眠,睡|活動
簡介=讓身體和大腦休息、修復的時間
時間=成人每天大約需要 7 到 9 小時；青少年 8 到 10 小時；小學生 9 到 12 小時
好處=整理記憶、修復身體、穩定情緒、增強免疫力
因:睡覺/要睡覺=睡覺時大腦會整理白天的記憶、清除代謝廢物，身體修復組織、分泌生長激素、調節免疫力；長期睡不夠，注意力、情緒、免疫力都會變差
@黑洞|黑洞|天體
簡介=引力強到連光都逃不出來的天體，通常是很大的恆星燒完、塌縮後形成的
說明=2019 年人類第一次拍到黑洞的照片（M87 星系中心的黑洞）
因:看不見/黑/黑色=黑洞的引力太強，連光都逃不出來，沒有光從裡面出來，所以是黑的；我們只能從它周圍被加熱發光的物質、還有它對附近星星的影響知道它在那裡
@銀河系|銀河|天體
簡介=太陽系所在的星系，是一個有一千億到四千億顆恆星的棒旋星系
大小=直徑大約 10 萬光年
說明=晚上在很暗的地方看到天上那條淡淡的光帶，就是從裡面看出去的銀河系
@引力|重力,萬有引力,地心引力|科學
簡介=有質量的東西彼此吸引的力量，讓我們站在地上、讓月亮繞著地球轉
說明=牛頓提出萬有引力定律，愛因斯坦的廣義相對論說引力是質量讓時空彎曲
因:往下掉/掉下來/會掉/東西/掉到地上=地球的質量很大，引力把所有東西往地心拉，所以東西放手就會往下掉
因:太空人飄/飄起來/無重力/失重=太空站裡其實還有大約九成的地球引力，太空人會飄，是因為太空站和他們一起不停地繞地球「往下掉」，同時又往前飛得夠快，一直掉不到地上，所以感覺不到重量
@電|電力,電流|科學
簡介=電荷流動產生的能量，可以讓燈亮、讓機器轉
說明=台灣家用電壓是 110 伏特，義大利和歐洲大部分是 230 伏特
因:觸電/電人=人體含有很多水和鹽分，會導電，電流通過身體會干擾心臟和神經，所以很危險
@磁鐵|磁石,吸鐵|科學
簡介=能吸引鐵的東西，有南極和北極兩端
說明=同極相斥、異極相吸；地球本身也是一個大磁鐵，所以指南針會指南北
因:吸鐵/會吸=磁鐵裡的原子小磁場排得很整齊，形成大的磁場；鐵靠近時，鐵裡的原子小磁場也被排整齊，就被吸過去
@細菌|病菌|生物
簡介=只有一個細胞的微小生物，到處都有，大部分無害，有些對人有益（例如腸道裡的好菌），少數會讓人生病
說明=細菌感染可以用抗生素治療；病毒不是細菌，抗生素對病毒沒有用
@病毒|病毒|生物
簡介=比細菌小很多、自己不能繁殖、要鑽進別的細胞裡才能複製的東西，會引起感冒、流感等疾病
說明=抗生素對病毒沒有用；預防病毒最好的方法是疫苗、勤洗手、戴口罩
@DNA|去氧核糖核酸|生物
簡介=記錄生物遺傳訊息的分子，像一本寫著怎麼打造你的說明書
形狀=雙螺旋，像扭轉的梯子；1953 年由華生和克里克提出
說明=人和人之間的 DNA 有大約 99.9% 相同
@人工智慧|AI,人工智能|科技
簡介=讓電腦學會理解、推理、學習的技術，例如辨識照片、翻譯、聊天
說明=現在的 AI 大多是用大量資料「訓練」出來的；我（NineSun）也是一個從零開始訓練的小 AI
看法=我覺得 AI 最好的用法是當人的幫手，讓人有更多時間做自己真正在乎的事
@火山|火山爆發|自然
簡介=地底下的岩漿從地殼的裂縫噴出地面形成的山
因:爆發/噴發/火山爆發=地底的岩漿溫度很高、含有大量氣體，比周圍的岩石輕，會往上擠；壓力累積到地殼撐不住的時候就噴發出來
說明=台灣的大屯火山群、義大利的維蘇威火山和埃特納火山都是有名的火山；維蘇威火山在西元 79 年掩埋了龐貝城
@溫室效應|全球暖化,地球暖化,氣候變遷|環境
簡介=大氣中的二氧化碳等氣體像溫室的玻璃一樣把熱留住；人類燒煤、石油、天然氣讓這些氣體變多，地球就越來越熱
因:暖化/變熱/全球暖化=燒煤、石油、天然氣和砍伐森林，讓大氣裡的二氧化碳、甲烷變多，把更多的熱留在地球上，平均氣溫就上升了
說明=全球平均氣溫已經比工業革命前上升了超過 1.2°C，會造成極端天氣、海平面上升
看法=我覺得每個人都能做點小事：少用一次性塑膠、多搭大眾運輸、省電，加起來就很可觀
@塑膠|塑料,塑膠袋|環境
簡介=用石油做成的材料，便宜好用，但在自然環境裡要幾百年才會分解
說明=海洋裡的塑膠垃圾會被海龜、海鳥誤吃；分解成的微塑膠已經在海水和食物裡被發現
@近視|近視眼|身體
簡介=看近的清楚、看遠的模糊，因為眼球太長，光線聚焦在視網膜前面
因:近視/會近視=長時間近距離看書、看手機，眼睛一直在用力看近的，加上待在室內太久、太少到戶外看遠處和曬太陽，眼球就容易變長，形成近視；父母近視的小孩也比較容易近視
說明=預防近視：每看近 30 分鐘休息 10 分鐘看遠處，每天到戶外活動 2 小時
@蛀牙|齲齒|身體
簡介=牙齒被細菌產生的酸侵蝕、出現小洞
因:蛀牙/會蛀牙=嘴巴裡的細菌吃了食物裡的糖，會產生酸，酸慢慢把牙齒的琺瑯質溶掉，就形成蛀牙；所以吃甜食後沒刷牙最容易蛀牙
說明=預防蛀牙：早晚用含氟牙膏刷牙、用牙線、少吃甜食和含糖飲料、定期看牙醫
@刷牙|刷牙|活動
簡介=用牙刷和牙膏清潔牙齒，把牙菌斑刷掉
時間=每次刷 2 分鐘，早晚各一次
好處=預防蛀牙和牙周病，口氣也比較清新
因:刷牙/要刷牙=吃完東西後，細菌會在牙齒上形成牙菌斑，吃糖產生酸、破壞牙齒，還會讓牙齦發炎，刷牙就是把牙菌斑刷掉
@維他命C|維生素C|營養
簡介=身體自己不能製造、要從食物攝取的維生素，幫助傷口癒合、維持免疫力、幫助吸收鐵
好處=幫助製造膠原蛋白、維持免疫力、抗氧化、幫助吸收鐵質
說明=芭樂、奇異果、柑橘、草莓、甜椒都含很多維他命C；吃維他命C預防感冒的效果其實有限
@蛋白質|蛋白|營養
簡介=構成肌肉、皮膚、頭髮、酵素的營養素
好處=修復和建造肌肉、維持免疫力、比較有飽足感
說明=雞蛋、豆腐、豆漿、魚、肉、牛奶都是好的蛋白質來源
@金字塔|埃及金字塔,吉薩金字塔|地標
簡介=古埃及法老的陵墓，最大的胡夫金字塔大約建於西元前 2560 年
高度=胡夫金字塔原本大約 146 公尺，現在大約 138 公尺
住=埃及開羅附近的吉薩
說明=是古代世界七大奇蹟中唯一還留存下來的
發明者=古埃及人蓋的。法老請工匠和數萬名工人建造（考古發現工人有領薪水、有醫療照顧，不是傳說中的奴隸，更不是外星人）
@萬里長城|長城|地標
簡介=中國古代為了抵擋北方游牧民族而修築的城牆，從春秋戰國開始修，秦朝把它連起來，現在看到的大多是明朝修的
長度=明長城大約 8,850 公里，歷代長城加起來超過 2 萬公里
說明=從太空用肉眼看得到長城是誤會，它太窄了
建造=長城不是一個人、一次蓋好的：春秋戰國時期（大約西元前 7 世紀起）各國就開始修築城牆；秦始皇統一六國後，把北方的城牆連接起來；現在看到最完整、最有名的部分，是明朝（1368 到 1644 年）大規模重新修築的
@艾菲爾鐵塔|巴黎鐵塔,鐵塔|地標
簡介=法國巴黎的地標，1889 年為了萬國博覽會建造
高度=大約 330 公尺
住=法國巴黎
說明=剛蓋好時很多藝術家覺得它很醜，現在卻是巴黎最受歡迎的景點
@羅馬競技場|競技場,圓形競技場|地標
簡介=古羅馬的大型圓形劇場，西元 80 年完工，可以容納大約五萬名觀眾觀看角鬥士的表演
住=義大利羅馬
說明=是古羅馬建築技術的代表，也是世界新七大奇蹟之一
@比薩斜塔|斜塔|地標
簡介=義大利比薩主教座堂的鐘樓，因為蓋在鬆軟的地基上而傾斜
住=義大利托斯卡尼的比薩
因:斜/歪/傾斜=比薩斜塔蓋在鬆軟的黏土和沙地上，才蓋到第三層地基就開始下沉、塔身傾斜；後來經過多次加固，現在傾斜大約 4 度，已經穩定下來
高度=大約 56 到 57 公尺
@台北101|101大樓,台北一零一|地標
簡介=台北的地標摩天大樓，2004 年完工
高度=508 公尺，2004 到 2010 年是世界最高的大樓
說明=大樓裡有一顆重 660 公噸的巨大阻尼球，用來減少颱風和地震時的晃動
年份=2004 年完工，12 月 31 日正式開幕
位置=台北市信義區，捷運台北101／世貿站旁
@奧運|奧林匹克運動會,奧運會,奧林匹克|活動
簡介=四年一次的國際運動會，起源於古希臘，1896 年在雅典舉辦第一屆現代奧運
說明=2024 年夏季奧運在法國巴黎，2026 年冬季奧運在義大利米蘭和科爾蒂納丹佩佐，2028 年夏季奧運在美國洛杉磯
特點=奧運五環代表五大洲
因:五環/五個環/奧運的環=奧運五環代表五大洲（藍、黃、黑、綠、紅五個環），環環相扣象徵世界各地的運動員在奧運相聚、團結；這五個顏色加上白色的底，可以組成當時每個國家國旗裡的顏色
頻率=每四年一次；夏季奧運和冬季奧運錯開兩年舉辦，所以每兩年就有一次奧運
因:下一屆/下次/下一次=下一屆夏季奧運是 2028 年美國洛杉磯，冬季奧運是 2030 年法國阿爾卑斯山區
因:台灣金牌/台灣得過/台灣拿過/中華台北=台灣（中華台北）到 2024 年一共拿過 7 面奧運金牌：2004 年雅典跆拳道陳詩欣、朱木炎；2016 年里約舉重許淑淨；2020 年東京舉重郭婞淳、羽球男雙李洋／王齊麟；2024 年巴黎羽球男雙李洋／王齊麟（連霸）、拳擊林郁婷
@世界盃|世界杯,世足,世界盃足球賽,FIFA世界盃|活動
簡介=四年一次的國際足球賽，是全世界最多人看的運動賽事
說明=巴西拿過 5 次冠軍最多；義大利拿過 4 次；2022 年冠軍是阿根廷；2026 年由美國、加拿大、墨西哥合辦
頻率=每四年一次，通常在奧運的中間年舉辦
@諾貝爾獎|諾貝爾,諾貝爾獎金|活動
簡介=依照瑞典化學家諾貝爾的遺囑設立的獎，1901 年開始頒發，分物理、化學、生理醫學、文學、和平，後來加了經濟學
說明=頒獎典禮在每年 12 月 10 日（諾貝爾的忌日），和平獎在挪威奧斯陸頒發，其他在瑞典斯德哥爾摩
發明者=瑞典化學家阿佛烈·諾貝爾，他發明了矽藻土炸藥，用財產設立了這個獎
@聯合國|UN|組織
簡介=1945 年成立的國際組織，目的是維護世界和平、促進國際合作
住=總部在美國紐約
說明=目前有 193 個會員國；安全理事會有 5 個常任理事國：美國、英國、法國、俄羅斯、中國
年份=1945 年 10 月 24 日正式成立，總部在美國紐約
@歐盟|歐洲聯盟|組織
簡介=歐洲國家組成的政治和經濟聯盟，成員國之間人員、貨物可以自由流通，很多國家共用歐元
說明=目前有 27 個成員國，英國在 2020 年退出
@聖母峰|珠穆朗瑪峰,珠峰,埃佛勒斯峰,額菲爾士峰|地標
簡介=世界最高的山，在中國和尼泊爾的邊界，屬於喜馬拉雅山脈
高度=海拔 8848.86 公尺（2020 年中國和尼泊爾共同公布的數字）
說明=1953 年紐西蘭的希拉里和雪巴人丹增·諾蓋第一次登頂
位置=中國西藏和尼泊爾的交界，喜馬拉雅山脈
因:第一個登頂/第一個爬/第一次登頂/誰爬上/首次登頂=1953 年 5 月 29 日，紐西蘭的艾德蒙·希拉里和雪巴人丹增·諾蓋第一次登上聖母峰頂
@玉山|新高山|地標
簡介=台灣最高的山，也是東北亞最高峰
高度=海拔 3952 公尺
說明=在南投、嘉義、高雄交界，是玉山國家公園的中心
位置=南投縣信義鄉和嘉義縣阿里山鄉的交界（主峰），屬於玉山國家公園
@富士山|富士山|地標
簡介=日本最高的山，是一座活火山，也是日本的象徵
高度=海拔 3776 公尺
說明=最後一次噴發是 1707 年；2013 年列入世界文化遺產
位置=日本本州中部，靜岡縣和山梨縣的交界
登山=可以。每年大約 7 月上旬到 9 月上旬是開山期，這段時間才開放一般人登山；最熱門的是吉田路線，從五合目出發，上山大約 5 到 7 小時，很多人會在山屋休息、半夜再出發看日出（御來光）。山頂很冷，也可能有高山症，要帶保暖衣物；近年山梨、靜岡兩邊都開始收入山費、有人數管制，出發前要查最新規定
最佳季節=想看清楚的富士山，冬天到早春（大約 12 月到 2 月）空氣乾燥、能見度最好；4 月可以看櫻花配富士山（河口湖一帶），11 月有紅葉；想登山就要選 7 到 9 月的開山期
@阿里山|阿里山|地標
簡介=台灣嘉義的著名山區和風景區，以日出、雲海、森林鐵路和神木聞名
高度=主峰塔山大約海拔 2663 公尺；遊樂區大約 2200 公尺
位置=台灣嘉義縣阿里山鄉
交通=最方便是從高鐵嘉義站或嘉義火車站搭台灣好行（阿里山線）公車上山，大約 2 到 2.5 小時；也可以從嘉義站搭阿里山林業鐵路（班次少，要提早訂票）；自己開車走台 18 線阿里山公路，山路彎多，容易暈車的人記得先吃藥
@馬里亞納海溝|馬里亞納海溝,挑戰者深淵|地標
簡介=世界最深的海溝，在西太平洋
長度=大約 2550 公里長
說明=最深的地方叫挑戰者深淵，大約 10,900 多公尺深（大約 1 萬 1 千公尺）
@股票|股份,股市|經濟
簡介=公司把所有權分成很多小份賣給大家，買了股票就成了這家公司的股東，擁有一小部分
說明=公司賺錢時可能發股利，股價也會跟著公司的表現和市場的看法漲跌；股票有賺有賠，不保證獲利
@通貨膨脹|通膨,通脹|經濟
簡介=物價全面而且持續上漲的現象，同樣的錢能買到的東西變少了
說明=適度的通膨（一年 2% 左右）被認為是正常的；太高會讓存款縮水，央行常用升息來壓通膨；相反的現象叫通貨緊縮
例子=十幾年前一碗滷肉飯大約 30 元，現在常常要 40 到 50 元；同樣拿 100 元去買東西，能買到的變少了，這就是通貨膨脹
@GDP|國內生產毛額,國內生產總值|經濟
簡介=國內生產毛額（Gross Domestic Product），一個國家一年之內生產的所有最終商品和服務的總價值，是衡量經濟規模最常用的數字
說明=除以人口就是「人均 GDP」，比較能看出生活水準
@利率|利息|經濟
簡介=借錢的價格：借錢要多付的錢（利息）佔本金的比例
說明=央行升息會讓借錢變貴、壓抑通膨；降息會刺激消費和投資
例子=把 10 萬元存一年定存、年利率 1.5%，一年後拿到 1,500 元利息；反過來借 10 萬元、年利率 5%，一年要多付 5,000 元利息
@區塊鏈|區塊鏈技術,blockchain|科技
簡介=一種去中心化的記帳技術：交易紀錄寫進一個個「區塊」，用密碼學串成一條鏈，由很多電腦一起保存，很難被竄改
說明=比特幣就是建立在區塊鏈上；它的好處是不用靠銀行這樣的中間人也能互相信任
@量子電腦|量子計算,量子計算機|科技
簡介=用量子力學的原理計算的電腦：一般電腦的位元只能是 0 或 1，量子位元可以同時是 0 和 1（疊加），讓某些問題算得非常快
說明=現在還在發展中，容易出錯、需要接近絕對零度的低溫；未來可能用在破解密碼、新藥和材料研究
@元宇宙|Metaverse|科技
簡介=一個用虛擬實境、擴增實境和網路打造的虛擬世界，人可以用虛擬分身在裡面工作、社交、玩樂
說明=臉書在 2021 年因此改名 Meta，但熱潮後來退燒
@碳中和|淨零排放,淨零,碳排放中和|環境
簡介=把排放的二氧化碳（溫室氣體）減到最少，剩下的再用種樹、碳捕捉等方式抵銷，讓淨排放變成零
說明=很多國家的目標是 2050 年達到淨零排放，用來減緩全球暖化
@ESG|ESG|經濟
簡介=評估一家公司是不是永續經營的三個面向：環境（Environmental）、社會（Social）、公司治理（Governance）
說明=投資人越來越重視 ESG，不只看公司賺多少錢
@疫苗|預防針,打疫苗|科學
因:運作/怎麼運作/原理/有效/有用/保護=疫苗是讓免疫系統先「預習」：打進去的是減弱或死掉的病原體、它的一小部分，或是教細胞做出病原體某個蛋白質的 mRNA；免疫系統認出這些「通緝照片」，做出抗體和記憶細胞。以後真的病毒或細菌進來，身體認得它，很快就能大量製造抗體把它消滅，所以不容易生病，或症狀比較輕
發明者=英國的詹納在 1796 年用牛痘預防天花，做出第一種疫苗；後來法國的巴斯德發展出更多疫苗
簡介=用減弱、死掉的病原體或它的一部分做成的東西，打進身體後讓免疫系統先學會認識它、產生抗體，以後真的感染時就能快速對抗
說明=第一種疫苗是 1796 年英國的詹納用牛痘預防天花
@基因|基因組|生物
簡介=DNA 上帶有遺傳訊息的片段，決定生物的各種特徵（像眼睛顏色、血型），會從父母遺傳給孩子
說明=人大約有兩萬個左右的基因
@人體骨頭|骨頭,骨骼|人體
簡介=支撐身體、保護內臟的組織
說明=成年人大約有 206 塊骨頭；剛出生的嬰兒大約有 270 到 300 塊，長大時有些會長在一起
@基金|共同基金,ETF,指數型基金|經濟
簡介=把很多人的錢集合起來，交給專業的公司去投資股票、債券等，賺賠由大家依比例分；ETF 是在股市交易的基金，指數型基金跟著大盤指數買一籃子股票
說明=好處是分散風險、小錢就能投資；要注意管理費，而且基金也會賠錢，不保證獲利
@第二次世界大戰|二戰,二次大戰,第二次大戰,二次世界大戰|事件
簡介=1939 年到 1945 年的世界大戰，一邊是德國、日本、義大利等軸心國，一邊是英國、美國、蘇聯、中國等同盟國
年份=1939 年 9 月德國入侵波蘭開始，1945 年結束（5 月德國投降，8 月日本宣布投降，9 月 2 日正式簽署投降書）
說明=是人類史上死傷最多的戰爭，大約有 7 千萬到 8 千 5 百萬人死亡；戰後成立了聯合國
@第一次世界大戰|一戰,一次大戰,第一次大戰,一次世界大戰|事件
簡介=1914 年到 1918 年以歐洲為主戰場的世界大戰
年份=1914 年 7 月開始，1918 年 11 月 11 日停戰
說明=導火線是奧匈帝國的皇儲在塞拉耶佛被刺殺
@登陸月球|人類登陸月球,登月,阿波羅11號,阿姆斯壯登月|事件
