說明=使用歐元的國家（歐元區）大約有二十個，像德國、法國、義大利、西班牙、荷蘭、比利時、奧地利、葡萄牙、希臘、愛爾蘭、芬蘭、克羅埃西亞等；丹麥、瑞典、波蘭這些歐盟國家沒有用歐元
@Wi-Fi|WiFi,wifi,無線網路|科技
簡介=讓手機、電腦不用接線、用無線電波連上網路的技術
說明=家裡的 Wi-Fi 是由無線路由器發出訊號，訊號會被牆壁擋住變弱
@5G|5G網路,第五代行動通訊|科技
