說明=原子非常小，大約一億個排起來才 1 公分；不同的原子（有多少個質子）就是不同的元素，像氫、氧、碳
@二氧化碳|CO2|科學
簡介=由一個碳原子和兩個氧原子組成的氣體（CO₂），無色無味
說明=人和動物呼吸會呼出二氧化碳，植物行光合作用會吸收它；它也是造成溫室效應的主要氣體之一
@牛頓第一定律|慣性定律|科學
簡介=慣性定律：物體如果沒有受到外力，靜止的會保持靜止，運動的會保持等速直線運動
說明=公車突然煞車時人會往前傾，就是因為身體想保持原本的運動；第二定律是 F = ma，第三定律是作用力與反作用力
@三角形|三角形|科學
