@魚類|魚類的呼吸|動物
簡介=住在水裡、用鰓呼吸、大多數有鱗片和鰭的脊椎動物
因:淹死/不會淹死/會淹死=魚用鰓呼吸：水流過鰓的時候，鰓會吸收溶在水裡的氧氣，所以在水裡不會「淹死」；不過如果水裡的氧氣太少（水太髒、太熱），魚還是會窒息
因:水裡呼吸/在水裡呼吸/呼吸/鰓=魚用鰓呼吸：水從嘴巴進去、流過鰓，鰓裡有很多微血管，可以把溶在水裡的氧氣吸進血液，再把二氧化碳排到水裡，所以魚不用浮上水面換氣
@散步|走路,快走|活動
簡介=最簡單、幾乎人人都能做的運動
好處=幫助血液循環和消化、強化心肺、穩定血糖、紓解壓力和焦慮、讓晚上比較好睡；每天快走 30 分鐘就能降低心血管疾病的風險
@吃早餐|早餐|活動
簡介=一天的第一餐
