@內向和外向|內向和外向的差別,內向外向差別,內向和外向有什麼不同,內向和外向的不同|常識
簡介=差別主要在「從哪裡得到能量」：外向的人跟人相處、熱鬧的環境會充電；內向的人獨處、安靜的時候才充得到電，社交久了會累。內向不等於害羞或不會說話，很多人是介在中間的「中間性格」
@社交恐懼|怎麼克服社交恐懼,社交恐懼怎麼辦,社恐怎麼辦,社交焦慮|常識
簡介=克服社交恐懼可以慢慢來：先從壓力小的場合練習，像跟店員多說一句話；事先想好幾個可以聊的話題；把注意力放在對方說什麼，而不是自己表現得好不好；每次做到就肯定自己；如果嚴重到不敢上班上課、心悸發抖，可以找心理師或精神科醫師，社交焦慮是可以治療的
