故事=鄉下紳士阿隆索讀太多騎士小說，自封騎士唐吉訶德，帶著農夫桑丘當隨從出門行俠仗義，把風車當成巨人衝過去、把旅店當成城堡，到處鬧笑話
結局=他被打敗回家，臨終前清醒過來，承認騎士小說是荒唐的，安詳死去
主題=理想與現實的衝突、瘋狂與清醒、堅持理想的可笑與可敬
