看法=很多人讀了覺得「這就是我」，所以它更提醒我們：覺得失格的時候，更要找人說說話
@刺激1995|肖申克的救贖,月黑高飛|作品
作者=法蘭克·戴瑞邦導演，改編自史蒂芬·金的中篇小說
類型=電影
地區=西方
年代=1994 年
簡介=常年在各大影評網站排名第一的美國電影
故事=銀行家安迪被冤枉殺妻，關進鯊堡監獄，和能弄到各種東西的瑞德成為朋友。他幫典獄長洗錢，同時花了將近二十年用小鎚子挖通牆壁
結局=安迪在暴雨夜從下水道逃出，揭發典獄長；瑞德假釋後照約定去墨西哥海邊找他
