看法=打遊戲、運動、畫畫時那種忘了時間的感覺，就是心流
@傷心咖啡店之歌|傷心咖啡店之歌|作品
作者=台灣的朱少麟
類型=長篇小說
地區=台灣
年代=1996 年
簡介=九〇年代台灣最暢銷的小說之一，寫一群年輕人追尋自由和人生意義
故事=都市上班族馬蒂厭倦了循規蹈矩的生活，離開工作和婚姻，走進台北一家叫「傷心咖啡店」的小店，認識了一群各有傷痕的年輕人，和他們討論自由、愛和生命的意義；她後來獨自去了馬達加斯加
結局=馬蒂在異鄉經歷了很多，最後在大自然裡結束了生命的旅程
主題=自由、孤獨、人生的意義、對體制的反叛
看法=很多人在二十幾歲讀到它，第一次認真問自己：我到底想怎麼活
@恐懼與戰慄|恐懼與顫慄|作品
作者=丹麥哲學家齊克果
類型=哲學著作
地區=西方
年代=1843 年
簡介=存在主義先驅齊克果的代表作之一
故事=以《聖經》裡亞伯拉罕聽從上帝要獻上兒子以撒的故事為中心，討論信仰為什麼是一種超越理性和道德的「信心的跳躍」
結局=是哲學著作，沒有故事結局
主題=信仰、倫理與信仰的衝突、個人的抉擇與焦慮
看法=它問了一個很難的問題：如果信仰要你做違背道德的事，你怎麼辦
@憂鬱的熱帶|憂鬱的熱帶|作品
作者=法國人類學家李維史陀
類型=人類學遊記
地區=西方
年代=1955 年
簡介=結構主義人類學大師李維史陀的經典，結合遊記、回憶和思考
故事=記錄他 1930 年代在巴西內陸和幾個原住民部落相處的經歷，也反省西方文明怎麼看待和破壞其他文化
結局=是遊記和思考，沒有故事結局
主題=文化的多樣性、對西方中心的反省、旅行的意義
看法=開頭第一句「我討厭旅行和探險家」很有名，因為他想說的遠不只是旅行
@悲傷逆流成河|悲傷逆流成河|作品
作者=中國的郭敬明
類型=長篇小說
地區=中國
年代=2007 年
簡介=寫校園霸凌和青春傷痛的小說，後來改編成電影
故事=上海弄堂裡長大的高中女生易遙，家境貧窮、母親不被鄰居尊重，在學校被同學霸凌、被謠言傷害；只有鄰居男孩齊銘對她好，但大人和流言讓一切越來越糟
結局=易遙在絕望中跳河自殺
主題=校園霸凌、流言的傷害、青春的孤獨
看法=它讓很多讀者第一次正視：旁觀和流言，也是一種傷害
@解憂雜貨店|解憂雜貨店|作品
作者=日本的東野圭吾
類型=長篇小說
地區=日本
年代=2012 年
簡介=東野圭吾最溫暖的作品之一，暢銷全世界
故事=三個闖了禍的年輕人躲進一間廢棄的雜貨店，發現店門口的信箱會收到三十多年前寄來的煩惱諮詢信；以前的老闆浪矢爺爺會認真回信，他們也試著回信，幾封信串起了很多人的人生
結局=他們發現所有的事都跟同一間孤兒院有關，也和自己有關；最後收到一封空白信的回信，決定重新面對人生
主題=迷惘與選擇、善意的連結、人生的地圖是白紙
看法=它說：煩惱的人其實心裡已經有答案，只是需要有人推一把
