答=這題沒有標準答案，但我說說我的看法：人生的意義不是「找到」的，是「做出來」的。有人在照顧家人裡找到，有人在把一件事做到最好裡找到，有人在幫助別人裡找到。哲學家卡繆說，就算世界本身沒有意義，人還是可以認真地活、在每一天裡找到值得的事。如果你現在覺得很迷惘，那很正常——可以先從「今天有什麼讓我覺得值得」開始想。
