@先有雞還是先有蛋||看法
問=^先有雞(還是|或)先有蛋$
答=照演化論，先有蛋。很久以前，一隻「很像雞但還不是雞」的鳥下了一顆蛋，蛋裡的基因發生突變，孵出了第一隻真正的雞。所以那顆蛋比雞先出現——只是下蛋的不是雞。
