@該不該分手||選擇
問=^(我)?(該不該|要不要|應不應該|應該)(跟.{0,4})?(分手|離婚)(嗎|呢)?$
答=分手是很重的決定，先想想這幾件事：⏎1. 你們的問題是「可以溝通改善的」（習慣、溝通方式），還是「價值觀根本不同」（要不要小孩、要住哪、對忠誠的看法）？⏎2. 你有好好說出你的感受嗎？他知道你有多難受嗎？⏎3. 跟他在一起時，你大部分時間是比較像自己，還是越來越不像自己？⏎4. 如果有暴力、控制、或讓你害怕的情況，安全最重要，請找信任的人或專業單位幫忙。⏎你想說說你們之間發生了什麼嗎？我會好好聽。
@該不該告白||選擇
問=^(我)?(該不該|要不要|應不應該|應該)(跟.{0,4})?(告白|表白|說喜歡他|說喜歡她)(嗎|呢)?$
答=我的看法：如果你們已經有一些互動、聊得來，告白的風險沒有想像中大。幾個小建議：⏎1. 先觀察他對你的回應：會主動找你聊、記得你說過的事，是好訊號。⏎2. 選一個輕鬆、兩個人獨處的時候，不要在很多人面前，給對方壓力。⏎3. 說清楚你的感覺就好，不用逼對方馬上回答。⏎4. 最壞的結果是被拒絕，會難過，但你會知道答案，不用一直猜。⏎想的話，告訴我你們的生日，我可以用九型十二宮幫你看看這段關係。
@怎麼交到男女朋友||選擇
問=^(要)?(怎麼|如何|怎樣才能|怎樣)(才能|才可以)?(交到|找到|追到|追)(男朋友|女朋友|男友|女友|另一半|對象|女生|男生)$
問=^(我)?(交不到|找不到)(男朋友|女朋友|男友|女友|對象)(怎麼辦)?$
答=沒有保證成功的方法，但這幾件事真的有用：⏎1. 擴大生活圈：參加有興趣的社團、課程、運動，在做喜歡的事時認識的人，本來就跟你比較合。⏎2. 先當朋友：多聊天、記住對方說過的事、真心好奇對方，比套路有用得多。⏎3. 照顧好自己：乾淨整齊、有自己的生活和興趣，自信的人比較有吸引力。⏎4. 主動一點：喜歡就約對方出來吃飯、看展，被拒絕也沒關係，代表你們不適合。⏎5. 不要急：太急的人容易隨便將就，緣分常常在你過得好的時候出現。⏎如果你告訴我生日，我也可以用九型十二宮看看你今年的桃花（5 宮）和感情走向。
@該不該出國||選擇
問=^(我)?(該不該|要不要|應不應該)(出國|去留學|出國念書|出國讀書|出國工作|去打工度假)(嗎|呢)?$
答=我覺得可以從這幾點想：⏎1. 目的：你想要的是學歷、語言、工作經驗，還是換個環境看看世界？目的清楚，選擇就清楚。⏎2. 錢：學費、生活費、機票，算一下要多少，家裡或自己能不能負擔；也可以查獎學金和打工度假。⏎3. 時機：現在出去，會不會錯過什麼？晚兩年出去，又會錯過什麼？⏎4. 回來的路：出國後想回來嗎？那段經歷能怎麼幫你？⏎如果條件允許，我通常會鼓勵年輕的時候出去看看，很多人說那是改變他們最多的一段時間。
@該不該買房||選擇
問=^(我)?(該不該|要不要|應不應該|現在適合)(買房|買房子|買房子嗎)(嗎|呢)?$
答=買房是很大的決定，我建議先算清楚：⏎1. 頭期款：通常要房價的兩成到三成，再加裝潢、稅費。⏎2. 每月房貸：最好不要超過收入的三分之一，還要預留緊急預備金（至少 6 個月的生活費）。⏎3. 你會在那個地方住多久？短期內可能搬家的話，租房比較彈性。⏎4. 不要只看房價會不會漲，要看你自己住得舒不舒服、通勤方不方便。⏎我不給投資建議，但我的看法是：買得起、住得久、不讓自己每個月都很緊，再買。
