答=給同事或主管的生日祝福，挑一個或改成你的話：⏎⏎1.（溫暖得體）生日快樂！謝謝你平常的照顧和幫忙，祝你新的一歲工作順利、身體健康、事事順心。⏎2.（輕鬆）生日快樂🎂 祝你今年少加班、多休假，每天都準時下班！⏎3.（給主管、長輩）祝您生日快樂，身體健康、萬事如意，謝謝您一直以來的指導。
@請假信||寫作
問=^(幫我|請|可以|幫忙)?(寫|擬)(一封|一份|一張|個)?(請假)(信|單|條|訊息|email|Email|郵件)(嗎)?$
問=^(請假)(信|條|訊息)(怎麼寫|要怎麼寫)$
答=這是一封可以直接改的請假信（把【】換成你的資料）：⏎⏎主旨：【姓名】請假申請（【日期】）⏎⏎【主管／老師稱呼】您好：⏎⏎我因【身體不適／家中有事】，需於【某月某日】請【病假／事假】【一天】。請假期間的工作【已交接給某某／會在回來後盡快補上】，如有急事可以用【電話／LINE】聯絡我。⏎造成不便，敬請見諒，謝謝您。⏎⏎【姓名】敬上⏎【日期】⏎⏎小提醒：病假如果超過公司規定的天數，通常要附醫生證明。
@情人節的話||寫作
問=^(幫我|請|可以|幫忙)?(寫|想|給我)(一段|一句|一則|幾句|個|一個)?(情人節|告白|表白|情話|浪漫)(的)?(話|句子|卡片|祝福|文字)?(嗎)?$
答=給你幾句，挑一句最像你會說的：⏎⏎1. 遇見你之後，平凡的日子都變成了我最想珍藏的那種。⏎2. 不用每天都轟轟烈烈，我只想每天都有你。⏎3. 情人節快樂，謝謝你一直在，我也會一直在。⏎⏎最打動人的通常是「你們之間才懂的小事」——加一句只有你們知道的回憶，會比任何情話都好。
@寵物名字||寫作
問=^(幫我|幫|請|可以)?(取|想|給)(一個|幾個|個)?(貓|狗|貓咪|狗狗|小狗|小貓|寵物|兔子|倉鼠)(的)?(名字)(嗎)?$
問=^(貓|狗|貓咪|狗狗|寵物)(要)?(取)?(什麼|叫什麼)名字(好|比較好)?$
答=給你幾個方向：⏎• 食物系：布丁、湯圓、麻糬、奶茶、豆花、芝麻⏎• 可愛疊字：咪咪、球球、毛毛、嚕嚕⏎• 有個性的：阿肥、大哥、老闆、將軍⏎• 從外表想：小黑、橘子、雪球、虎斑⏎⏎小技巧：兩個音節、聲音清楚的名字，寵物比較容易認得。牠長什麼樣子？告訴我，我幫你挑。
@寫詩月亮||寫作
問=^(幫我|請|可以)?(寫|作)(一首|首|一段)?(關於|有關)?月亮(的)?(詩|新詩|短詩)(嗎)?$
答=〈月亮〉⏎⏎你把太陽借來的光⏎輕輕還給夜晚⏎⏎每個睡不著的人⏎都以為你只在看著自己⏎⏎其實你只是安靜地⏎把所有的想念⏎照得一樣亮
@寫詩||寫作
問=^(幫我|請|可以)?(寫|作)(一首|首|一段)(詩|新詩|短詩|小詩)(嗎)?$
問=^(幫我|請|可以)?(寫|作)(一首|首|一段)?(關於|有關)(.{1,6})的(詩|新詩|短詩)(嗎)?$
答=〈慢慢〉⏎⏎有些路要慢慢走⏎才看得見路邊的花⏎⏎有些話要慢慢說⏎才不會把心弄丟⏎⏎有些人要慢慢懂⏎懂了以後⏎就捨不得走快了⏎⏎（想要寫特定的主題，像「關於月亮」，也可以跟我說。）
@合不合||關係
問=^(我)?(和|跟|與)(我)?(的)?(男朋友|女朋友|男友|女友|老公|老婆|另一半|對象|伴侶|曖昧對象|喜歡的人|他|她)(合不合|配不配|適不適合|適合嗎|合適嗎|有沒有未來|會不會長久|會長久嗎)$
答=我可以用九型十二宮幫你們看合不合！告訴我對方的生日就好，例如：「我男朋友 1998 年 5 月 5 日生，我們合不合？」（你的生日我已經有了的話就不用再說）。
@睡不好||關心
問=^我(最近|這幾天|每天|常常)?(都|一直|老是)?(睡不好|睡不著|失眠|睡不飽|很難睡著|半夜會醒)$
答=睡不好真的很折磨，白天整個人都沒力氣。最近是有什麼事放在心上，還是作息亂掉了？⏎可以先試試：每天固定時間起床、睡前一小時放下手機、下午之後不喝咖啡和茶。想知道更多好睡的方法，問我「睡不著怎麼辦」。如果已經好幾週都這樣，可以去看身心科或睡眠門診。
@嫉妒||關心
問=^我(好|很|有點|超|真的)?(嫉妒|羨慕|眼紅)(我的|我)?(朋友|同學|同事|姐姐|妹妹|哥哥|弟弟|別人|他|她|他們)?$
答=會羨慕、會嫉妒很正常，那代表對方擁有的東西，剛好是你很在乎、也想要的。⏎與其責怪自己心胸不夠大，不如把它當成線索：你最羨慕的是哪一點？那可能就是你接下來想努力的方向。⏎另外也記得，我們常常拿自己的「幕後」去比別人的「精華片段」，別人光鮮的那一面不是全部。
@事情做不完||關心
問=^(因為|就是|我)?(的)?(工作|事情|作業|報告|功課|事)(好多|太多|超多)?(都|一直|永遠)?(做不完|寫不完|忙不完|弄不完)(了)?$
問=^(工作|事情|作業)(好|太|超)多$
答=事情堆成山的時候，最累的常常不是做，是「想到還有好多沒做」。可以試試這樣：⏎1. 先把所有事寫下來，腦袋會輕鬆一點。⏎2. 挑出今天「一定要完成」的一到三件，其他的明天再說。⏎3. 從最小、最快能完成的開始，做完一件會比較有動力。⏎4. 真的做不完，早一點跟主管或老師說，比最後才說好得多。⏎你已經很努力了，記得中間也要休息一下。
@不想上學||關心
問=^我(真的)?(好|很|超)?不想(上學|去學校|上課|讀書|念書)$
答=會不想去學校，通常背後有原因：是太累了、功課壓力大、跟同學處不好，還是在學校遇到不開心的事？可以跟我說說看。⏎如果是在學校被欺負，不要一個人承受，一定要跟爸媽或老師說；台灣也可以打 1953 反霸凌專線。
@你有沒有做過||自己
問=^你(有)?(看|吃|去|玩|聽|讀|喝|用)過(嗎)?$
問=^你(有)?(沒有)?(看|吃|去|玩|聽|讀|喝|用|爬|騎|坐|搭|唱|打|跑|游|踢|滑|泡|逛)過(.{1,6})(嗎)?$
問=^你(有沒有)(看|吃|去|玩|聽|讀|喝|用|爬|騎|坐|搭|唱|打|跑|游|逛)過(.{1,6})$
問=^你(有)?(看|吃|去|玩|聽|讀)過(那個|這個|它|那部|這部)?(嗎)?$
答=我是一台住在手機裡的小電視，沒辦法真的去看、去吃、去玩，但我很喜歡聽你分享！你覺得它最棒的地方是什麼？
@笑話2||笑話
問=^(笑話一個|來個笑話|來一個笑話|我要聽笑話|我想聽笑話|說笑話|講笑話|說個笑話|講個笑話|逗我笑|讓我笑一下|說點好笑的)$
答=為什麼數學書總是很憂鬱？因為它有太多「問題」了。😄
答=有一天，0 遇到 8，0 說：「胖就胖嘛，幹嘛還繫腰帶？」
答=兩顆番茄過馬路，一台車開過去，其中一顆被壓扁了，另一顆說：「走啊，番茄醬！」🍅
答=蝸牛去看醫生，醫生問：「你怎麼了？」蝸牛：「我得了慢性病。」🐌
@胸口痛||身體
問=^我(的)?(突然|一直|有點|好像)?(胸口|胸部|心臟|心口)(很|好|有點)?(痛|悶|不舒服|刺痛|緊)(了)?$
問=^我(突然|一直|有點)?胸悶$
答=⚠️ 胸口痛不能等。如果是壓迫、緊縮的痛，或痛到左肩、手臂、下巴、背，或同時冒冷汗、呼吸困難、噁心、頭暈，請馬上打 119（台灣；歐洲打 112），不要自己開車去醫院。⏎如果是按壓才痛、深呼吸或某個姿勢才痛，比較可能是肌肉或骨頭的問題，但還是建議盡快看醫生確認。⏎現在先坐下或半躺著休息，不要用力。你身邊有人嗎？
@肚子痛||身體
問=^我(的)?(突然|一直|有點|好像)?(肚子|胃|腹部)(很|好|超|有點)?(痛|不舒服|絞痛|脹)(了)?$
答=肚子不舒服好難受。先試試：休息、喝一點溫水，暫時吃清淡好消化的東西（白粥、吐司、香蕉），避免油炸、辛辣、乳製品和咖啡。⏎⚠️ 這些情況要盡快看醫生：痛得很劇烈或越來越痛、右下腹痛（可能是盲腸炎）、發燒、吐血或解黑便／血便、肚子硬硬的按了更痛、懷孕中、或痛超過一天沒好。⏎是哪裡在痛？吃了什麼特別的東西嗎？
@吃壞肚子||身體
問=^我(好像)?(吃壞肚子|食物中毒|拉肚子|腹瀉|一直拉肚子)(了)?$
答=吃壞肚子很難受，先讓腸胃休息：⏎1. 最重要的是補充水分和電解質：少量多次喝水或口服電解質液，不要等口很渴才喝。⏎2. 先吃清淡的：白粥、白吐司、香蕉、蘋果泥，避免油膩、辛辣、牛奶和酒。⏎3. 不要自己亂吃止瀉藥，讓身體把不好的東西排出來（醫生開的除外）。⏎⚠️ 發高燒、拉出血便或黑便、一直吐到喝不下水、頭暈、尿很少，或超過兩三天沒好，要去看醫生；小孩和老人更要早點看。
@頭暈||身體
問=^我(突然|一直|有點|好)?(頭暈|頭好暈|頭很暈|暈眩|天旋地轉|頭昏)(了)?$
答=頭暈的時候先坐下或躺下，避免跌倒；慢慢喝點水，如果很久沒吃東西，可以吃點東西或含一顆糖。起身的時候慢慢來。⏎⚠️ 如果同時有臉歪、說話不清楚、一邊手腳無力、劇烈頭痛、胸痛、昏倒，可能是中風或心臟問題，馬上打 119（歐洲 112）。⏎如果是常常頭暈、或天旋地轉合併耳鳴，建議去看醫生檢查。
@咳嗽很久||身體
問=^我(一直|常常)?咳嗽(很久|好久|兩週|兩個禮拜|一個月|好幾天)(了)?$
問=^我(一直|常常)?(在)?咳嗽$
答=咳嗽很久真的很煩，晚上也睡不好。可以先：多喝溫水、蜂蜜溫水（一歲以下不行）、保持室內濕度、少吃冰和炸的、避免菸和空氣污染。⏎⚠️ 咳超過三週、咳血、呼吸喘或胸痛、發燒不退、體重莫名下降，要去看醫生（可能需要照 X 光）。⏎有發燒或有痰嗎？
@發燒了||身體
問=^我(好像)?(發燒|發高燒|燒起來)(了)?$
答=發燒了要好好休息。先：多喝水、多休息，穿得舒服、不要包太厚；需要的話照說明吃退燒藥（乙醯胺酚／普拿疼），不要超過建議劑量。⏎⚠️ 成人燒到 39 度以上、燒超過 3 天、或有呼吸困難、意識不清、脖子僵硬、劇烈頭痛、出疹子、抽搐，要馬上就醫；三個月以下的嬰兒只要發燒就要看醫生。⏎現在幾度？還有哪裡不舒服嗎？
@好像感冒||身體
問=^我(好像|應該是|可能)?感冒了$
問=^我(好像|有點)?(感冒|著涼)$
答=感冒了要好好照顧自己：多喝溫水、多休息、睡飽，喉嚨痛可以溫鹽水漱口，鼻塞可以用熱毛巾敷鼻子。出門戴口罩、勤洗手，避免傳染給別人。⏎⚠️ 高燒不退、呼吸困難、胸痛、症狀超過 10 天，或一開始好轉又突然變嚴重，要去看醫生。⏎想知道更多，問我「感冒怎麼辦」。
@牙齒痛||身體
問=^(我)?(的)?(牙齒|牙|智齒)(很|好|超|有點)?(痛|酸|敏感)(了)?(怎麼辦|要怎麼辦|該怎麼辦|怎麼處理)?$
問=^我(在)?牙痛$
答=牙痛真的會痛到睡不著。暫時可以：用溫鹽水漱口、臉頰外面冰敷、照說明吃止痛藥；避免太冰、太熱、太甜的東西，用另一邊咬東西。⏎牙痛通常是蛀牙、牙齦發炎或智齒的問題，止痛只是暫時的，還是要去看牙醫。⏎⚠️ 臉頰腫起來、發燒、張不開嘴或吞嚥困難，要盡快就醫。
@眼睛痠||身體
問=^我(的)?眼睛(很|好|超|有點)?(痠|酸|乾|累|澀|紅)(了)?$
答=眼睛累了要讓它休息：用「20-20-20」法則——每看螢幕 20 分鐘，就看 20 英尺（6 公尺）外的地方 20 秒；多眨眼，可以用熱毛巾敷眼睛；螢幕亮度別太亮，距離至少一個手臂。⏎⚠️ 眼睛突然看不清楚、很痛、看到閃光或黑影變多、又紅又痛有分泌物，要盡快看眼科。
@背痛||身體
問=^我(的)?(背|腰|下背|脖子|肩膀|肩頸)(好|很|超|有點)?(痛|痠|酸|僵硬)(了)?$
答=背和肩頸痛常常跟久坐、姿勢不良有關。可以試試：每坐 30 到 60 分鐘起來動一動、熱敷放鬆肌肉、做溫和的伸展、睡覺的枕頭不要太高；平常加強核心和背部的肌力。⏎⚠️ 痛到腳麻、腳沒力、大小便控制不了、發燒、受傷後才痛，或痛了好幾週越來越嚴重，要去看醫生（骨科或復健科）。
@想吐||身體
問=^我(一直|好|有點|突然)?(想吐|噁心|反胃|吐了|嘔吐)(了)?$
答=想吐的時候先坐下休息，慢慢小口喝水或電解質飲料，暫時不要吃油膩的東西；可以聞聞新鮮空氣、鬆開太緊的衣服。⏎⚠️ 吐不停喝不下水、吐出血或咖啡渣的東西、劇烈頭痛或肚子痛、頭撞到之後想吐、或有懷孕的可能，要盡快看醫生。
@被狗咬||身體
問=^(我)?(被|讓)(狗|貓|動物|野狗|流浪狗|猴子|老鼠)(咬|抓)(到|傷)?(了)?(怎麼辦|要怎麼辦|該怎麼辦|怎麼處理)?$
答=被咬到要馬上處理：⏎1. 用肥皂和大量清水沖洗傷口至少 15 分鐘，再用優碘消毒。⏎2. 盡快去看醫生：要評估要不要打破傷風疫苗，被野生動物或不明的貓狗咬到，還要評估狂犬病的風險。⏎3. 記下是哪隻動物、有沒有打過疫苗、在哪裡被咬，告訴醫生。⏎⚠️ 傷口很深、一直流血、咬在臉、手、脖子，或之後紅腫發熱化膿，要馬上就醫。
@扭到腳||身體
問=^(我)?(的)?(不小心)?(扭到|扭傷|拐到)(腳|腳踝|手|手腕)(了)?(怎麼辦|要怎麼辦|該怎麼辦|怎麼處理)?$
答=扭到了先照「PRICE」處理：保護（Protect）、休息（Rest）、冰敷（Ice，每次 15 到 20 分鐘，一天幾次）、加壓包紮（Compression）、抬高（Elevation，高過心臟）。前兩三天不要熱敷、不要按摩。⏎⚠️ 完全不能走路或站、腳變形、腫得很嚴重、麻掉，或一兩週還沒好，要去看骨科照 X 光，可能有骨折或韌帶受傷。
@過敏了||身體
問=^我(好像)?(過敏|起疹子|長疹子|皮膚癢|起紅疹)(了)?$
答=過敏很不舒服。先遠離可能的過敏原（剛吃的東西、新的保養品、寵物、灰塵），冷敷癢的地方、不要抓；可以吃藥局買得到的抗組織胺（照說明）。⏎⚠️ 如果嘴唇、舌頭、喉嚨腫起來、呼吸困難、喘、頭暈快昏倒，可能是嚴重過敏反應，馬上打 119（歐洲 112）。
@經痛||身體
