答=我想去看一次真正的星空！還有試試番茄炒蛋配白飯到底是什麼味道、在雨天窩在咖啡廳看書、跟你見面聊天。你呢，如果有一天什麼都不用管，你想做什麼？
@我該學什麼||選擇
問=^你覺得我(應該|該|要)學(什麼|甚麼)$
問=^我(應該|該|要)學(什麼|甚麼)(好|比較好)?$
答=要看你想要什麼：⏎・想增加工作機會：英文、Excel／資料分析、寫程式、AI 工具，都很實用⏎・想讓生活更有趣：一樣樂器、攝影、做菜、一個運動⏎・想照顧自己：理財、心理學、睡眠和飲食的知識⏎⏎我的建議是挑一個「你本來就有點好奇」的，從每天 15 分鐘開始。你現在對什麼最有興趣？
@貓狗哪個可愛||看法
問=^你覺得(貓|貓咪)(比較)?可愛還是(狗|狗狗)(比較)?可愛$
問=^你覺得(狗|狗狗)(比較)?可愛還是(貓|貓咪)(比較)?可愛$
問=^(貓|狗)(跟|和)(狗|貓)(哪個|誰)(比較)?可愛$
答=兩個都好可愛！硬要選的話……貓咪那種「我愛理不理但其實很在意你」的樣子很好笑；狗狗看到你就搖尾巴的熱情也讓人融化。我選不出來，你是貓派還是狗派？
@情詩||寫作
問=^(幫我|請|可以)?(寫|想|作)(一首|首|一段)?(情詩|愛情詩|告白詩|給(女朋友|男朋友|老婆|老公|另一半)的詩)$
答=〈剛好〉⏎⏎世界上有那麼多條路⏎我剛好走到你身邊⏎⏎有那麼多個清晨⏎我剛好想起你⏎⏎沒有什麼了不起的理由⏎只是每一個剛好⏎都讓我更確定⏎是你⏎⏎（想要更甜、更搞笑，或加上你們的名字和回憶，跟我說，我幫你改。）
@道歉的話||寫作
問=^(幫我|請|可以)?(寫|想)(一段|一些|幾句|一封)?(道歉|對不起)(的話|的訊息|信|的信)?$
答=給你一段可以改的道歉訊息：⏎⏎「對不起，那天是我不好。我【說了／做了什麼】，讓你覺得【受傷／不被尊重】，這不是你應該承受的。我想了很久，以後我會【具體怎麼改】。如果你願意，我想當面好好跟你說一次對不起。」⏎⏎重點是說清楚自己做錯什麼、承認對方的感受、說之後怎麼改，不要加「但是」。告訴我發生了什麼，我可以幫你寫得更貼切。
@感謝老師||寫作
問=^(幫我|請|可以)?(寫|想)(一段|一些|幾句|一張)?(感謝|謝謝)(老師|教授|導師)(的話|的卡片|的訊息)?$
問=^(教師節|畢業)(要)?(寫|送)(給)?老師(的話|什麼話|卡片)$
答=給你兩種，挑一個改成你的話：⏎⏎1.（溫暖）「老師，謝謝您這段時間的耐心和用心。您說過的話我會一直記得，也會帶著您教我的東西繼續往前走。祝您身體健康、教學順心！」⏎⏎2.（輕鬆）「謝謝老師把我從『完全聽不懂』教到『好像有點懂了』！辛苦您了，以後我也會繼續努力，不讓您失望。」⏎⏎加上一件跟老師之間的具體小事（某堂課、某句鼓勵），會更感人。
@生日禮物||選擇
