問=^生日禮物(要)?(送什麼|買什麼)(好|比較好)?$
答=生日禮物可以從這幾個方向想：⏎・對方最近提過想要的東西（最加分）⏎・跟興趣有關的：喜歡咖啡就送好豆子或手沖器材，愛運動送運動耳機或毛巾⏎・實用又有質感：香氛蠟燭、好的保溫杯、圍巾、按摩器⏎・一起的體驗：吃一頓好餐廳、看一場表演⏎・心意型：手寫卡片＋你們的照片⏎⏎跟我說是送誰、他平常喜歡什麼、預算多少，我幫你挑得更準。
@英文名字||寫作
問=^(幫我|請|可以)?(取|想|起)(一個|個|幾個)?(英文名字|英文名|外文名字)$
答=給你幾個好唸、好記的英文名字：⏎・女生：Emma、Olivia、Chloe、Grace、Mia、Iris、Luna⏎・男生：Ethan、Lucas、Ryan、Leo、Aaron、Daniel、Owen⏎⏎選的時候可以挑跟中文名字發音接近的，或是喜歡它的意思（像 Grace 是優雅、Leo 是獅子）。告訴我你的中文名字和想要的感覺，我可以幫你挑更適合的。
