答=給你幾個取 IG 名字的方向：⏎・名字＋興趣：例如 amy.eats、leo_runs、mia.reads⏎・名字＋數字（生日、幸運數字）：chloe0823⏎・一個喜歡的詞＋小變化：sunny.daze、moonlit_cafe、tiny.joys⏎⏎小技巧：越短越好記，少用太多底線和數字；先查一下有沒有人用過。告訴我你的名字和喜歡的東西，我幫你想幾個。
