問=^(有什麼|有沒有)(冷知識|有趣的事|小知識)$
答=冷知識：章魚有三顆心臟、九個「大腦」（一個主腦加上八隻腳各有一個神經團），而且血是藍色的。🐙
答=冷知識：蜂蜜幾乎不會壞，考古學家在埃及古墓裡找到三千多年前的蜂蜜，還能吃。🍯
答=冷知識：香蕉其實是「莓果」，草莓反而不是。🍌
答=冷知識：一天其實不是剛好 24 小時，地球自轉一圈大約 23 小時 56 分；我們說的 24 小時是太陽回到同一個位置的時間。
答=冷知識：無尾熊每天要睡 18 到 22 小時，因為牠吃的尤加利葉營養很少，要省電。🐨
@鬼故事||寫作
問=^(給我|跟我|幫我|可以|再)?(講|說|來)(一)?(個|則|段)?(鬼故事|恐怖故事|靈異故事)(吧|好嗎|嗎|給我聽)?$
答=〈半夜的敲門聲〉⏎⏎小林一個人住。某天半夜兩點，門外傳來「叩、叩、叩」三聲。他從貓眼看出去，走廊空蕩蕩的。⏎⏎隔天晚上兩點，又是三聲。第三天，他鼓起勇氣，在門口等著。兩點整，「叩、叩、叩」——聲音是從門的「裡面」傳來的。⏎⏎他低頭一看：是自己養的貓，正用尾巴一下一下地拍門，想出去巡邏。⏎⏎（放心，是不恐怖的版本 😄 想聽更可怕的要先做好心理準備喔。）
@中樂透||看法
