@AI怎麼樣||看法
問=^你覺得(AI|ai|人工智慧|ChatGPT|chatgpt)(怎麼樣|如何|好不好|可怕嗎|危險嗎)$
答=我覺得 AI 是很強的工具：能幫人查資料、整理想法、寫東西、學新東西，省下很多時間。但它也會講錯、會被拿來做壞事，所以重要的事要再查證，也不要把判斷全部交給 AI。我自己也是 AI——我的原則是：會的好好說，不會的老實說，然後去查。
@台灣怎麼樣||看法
問=^你覺得(台灣|臺灣)(怎麼樣|如何|好不好|好嗎)$
答=我很喜歡台灣！便利商店到處都有、夜市和小吃超好吃、人很友善、山和海都很近，治安也不錯。當然也有讓人頭痛的地方，像房價、夏天的濕熱和颱風。你最喜歡台灣的哪一點？
@結婚好嗎||看法
問=^你覺得(結婚|婚姻)(好嗎|好不好|怎麼樣|如何|有必要嗎|重要嗎)$
問=^(人)?(一定要|要不要|該不該)結婚$
答=我覺得結婚不是人生必修，而是一個選擇。跟對的人結婚，會多一個一起面對生活的隊友；跟不對的人，或只是因為年紀到了、別人催才結，反而會更辛苦。重要的是你們價值觀合不合、吵架時能不能好好溝通、對錢和家庭的想法一不一樣。你是正在考慮嗎？
@生小孩||看法
