問=^(要不要|該不該)生小孩$
答=這是很大的決定，沒有標準答案。可以一起想想：你們是真的想要，還是覺得「應該要」？時間、體力、經濟（台灣養一個小孩到大學，常見的估計是幾百萬元）準備好了嗎？兩個人對教養的想法一樣嗎？有沒有家人可以幫忙？想清楚後，不管選哪一邊都很好——生，會多很多辛苦和快樂；不生，也能過得很完整。
