答=我覺得有用，但用處不只是那張文憑：大學最值錢的是你學會怎麼自己學東西、認識一群朋友、有幾年時間試試看自己喜歡什麼。如果只是為了混一張文憑，就比較可惜；如果你已經很清楚要做什麼（像技術、創業），先工作、邊做邊學也是一條路。
