答=我覺得兩個都重要，但順序是：先有「夠用的錢」，再追求快樂。研究發現，收入從不夠用到夠用，幸福感會明顯上升；但超過某個程度之後，多賺的錢帶來的快樂就沒那麼多了。所以先讓生活穩定，之後把時間留給喜歡的人和事，是我覺得最划算的選擇。
