答=要不要辭職，可以先問自己幾個問題：⏎1. 讓你想走的，是工作本身、主管同事，還是太累？有些問題換部門或休假就能解決。⏎2. 存款夠不夠撐 3 到 6 個月？⏎3. 下一步想清楚了嗎？最好是「騎驢找馬」，找到下一份再走。⏎4. 如果已經影響身體和心理健康，那健康優先。⏎⏎你現在最想離開的原因是什麼？說說看，我陪你一起想。
