問=^什麼是(開源模型|開源大腦)$
答=App 裡有一個「開源模型」的開關：打開之後，你的每一句話都會直接交給手機上的開源大型語言模型（例如 Gemma）回答，聊天比較自由；關掉的時候，是我自己的引擎在回答——九型十二宮和命盤計算、我自己的常識庫，不知道的再上網查。兩種可以隨時切換。
